    @Test
    public void testParseMultipleCronExpressionsIntoCompositeCron() {
        // Objective: Verify that multiple cron expressions are accurately parsed into a composite cron object.

        // Preconditions
        String multiCronExpression = "0 0 12 * * ? || 0 15 10 * * ? || 0 0 10 * * ?";

        // Action
        Cron cron = parser.parse(multiCronExpression);

        // Expected Results
        assertTrue(cron instanceof CompositeCron, "The parsed cron should be an instance of CompositeCron.");

        CompositeCron compositeCron = (CompositeCron) cron;
        assertEquals(3, compositeCron.getCrons().size(), "CompositeCron should contain three individual cron expressions.");

        // Verify each individual cron expression
        String[] expressions = multiCronExpression.split("\\|\\|");
        for (int i = 0; i < expressions.length; i++) {
            Cron individualCron = compositeCron.getCrons().get(i);
            String[] parts = expressions[i].trim().split(" ");
            assertEquals(parts.length, individualCron.retrieveFieldsAsMap().size(),
                "The number of fields in the individual cron should match.");
            // Additional checks can be added based on field values
        }
    }
}

