package com.cronutils.model;

import com.cronutils.model.definition.CronDefinition;
import com.cronutils.model.definition.CronDefinitionBuilder;
import com.cronutils.parser.CronParser;
import org.junit.jupiter.api.Test;

import java.util.ArrayList;
import java.util.List;

import static org.junit.jupiter.api.Assertions.*;

public class CompositeCronTest {

    @Test
    public void testEquivalent() {
        // Set up cron definition and parser for Quartz type
        CronDefinition definition = CronDefinitionBuilder.instanceDefinitionFor(CronType.QUARTZ);
        CronParser parser = new CronParser(definition);

        // Parse cron expressions
        Cron cron1 = parser.parse("0 0 0 15 8 ? 2015/2");
        Cron cron2 = parser.parse("0 0 0 16 9 ? 2015/2");
        Cron cron3 = parser.parse("0 0 0 17 10 ? 2015/2");

        // Create first composite cron with cron1 and cron2
        List<Cron> cronList1 = new ArrayList<>();
        cronList1.add(cron1);
        cronList1.add(cron2);
        CompositeCron compositeCron1 = new CompositeCron(cronList1);

        // Create second composite cron with cron2 and cron3
        List<Cron> cronList2 = new ArrayList<>();
        cronList2.add(cron2);
        cronList2.add(cron3);
        CompositeCron compositeCron2 = new CompositeCron(cronList2);

        // Assert that a composite cron is equivalent to itself
        assertTrue(compositeCron1.equivalent(compositeCron1));

        // Assert that two different composite crons are not equivalent
        assertFalse(compositeCron1.equivalent(compositeCron2));
    }
}

