protected List<Integer> generateCandidatesNotIncludingIntervalExtremes(int start, int end) {
    // start is the day of month to start from
    List<Integer> candidates = new ArrayList<>();
    int reference = start;
    try {
        while (reference < end) {
            reference = generateNextValue(reference);
            if (reference < end) {
                candidates.add(reference);
            }
        }
    } catch (NoSuchValueException ignored) {
        // next generated value would be beyond the end of the month, so just ignore it and finish
    }
    return candidates;
}

public final List<Integer> generateCandidates(final int start, final int end) {
    List<Integer> candidates = generateCandidatesNotIncludingIntervalExtremes(start, end);
    if (isMatch(start)) {
        candidates.add(start);
    }
    if (isMatch(end)) {
        candidates.add(end);
    }
    candidates = new LinkedList<>(new HashSet<>(candidates));
    Collections.sort(candidates);
    return candidates;
}

