    boolean match = false;
    for (final FieldExpression expression : and.getExpressions()) {
        match = match || createCandidateGeneratorInstance(new CronField(cronField.getField(), expression, cronField.getConstraints())).isMatch(value);
    }
    return match;
}

public final List<Integer> generateCandidates(final int start, final int end) {
    List<Integer> candidates = generateCandidatesNotIncludingIntervalExtremes(start, end);
    if (isMatch(start)) {
        candidates.add(start);
    }
    if (isMatch(end)) {
        candidates.add(end);
    }
    candidates = new LinkedList<>(new HashSet<>(candidates));
    Collections.sort(candidates);
    return candidates;
}

